quests[78443] = { id = 78443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystalsong Crisis - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78444] = { id = 78444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Ally: Dream Wardens", description = "So much change to that which should be unchanging... \n\nRarely has the Dream seen such turmoil. It is meant to be a place of peace. Of life. \n\nChampion, we need all the help we can get. I bid you go forth and bring aid to the expanse of the Dream.\n\nI have no doubt the Dream will share its plenty with you in return.", progress = "Do take some time to stop and smell all that blooms throughout the Dream. It will enrich your life.", completion = "<Keeper Amrymn takes a deep breath.> \n\nThe air has gone calm. Peace returns to the Dream, even if slowly.\n\nAll who keep and defend this place thank you, hero.", objectives = "Aid the Dream Wardens and their allies throughout the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78446] = { id = 78446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: Superbloom", description = "As life blooms within the Emerald Dream, the budding World Tree Amirdrassil blooms with it. \n\nThe Ancient Sprucecrown's ritual empowers mighty life energies all around the tree, encouraging its growth. The more hands there to help protect and nourish Amirdrassil, the better its bloom will be! \n\nPlease lend your aid to Sprucecrown on his journey.", progress = "I do hope you don't suffer from allergies.", completion = "Ah, I can almost smell the flowers on the wind from here!\n\nPlease accept this humble gift, along with our gratitude.", objectives = "Travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78447] = { id = 78447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: Emerald Bounty", description = "The Emerald Dream suffers at the forces of the Incarnate Fyrakk. In its turmoil, some of its seeds have trouble taking root. \n\nIn exploring the Dream, I am certain you shall collect some special seeds. Plant them in soil and nourish them into a bloom, and I hear they will share bountiful gifts with you.\n\nGo forth and help life blossom in the Emerald Dream!", progress = "I wonder what gifts a flower can bestow?", completion = "The Dream is such a strange place!\n\nPlease accept this humble gift, along with our gratitude.", objectives = "Travel to the Emerald Dream and plant 3 Dreamseeds of any quality in Emerald Bounty soil. Dreamseeds can be acquired from most activities in the Dream. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78452] = { id = 78452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements - Activate" }
