quests[78456] = { id = 78456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonblight Dragon Flight - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78457] = { id = 78457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Dornogal", description = "I am Merrix, Councilward of Dornogal.\n\nI appreciate your aid--especially in light of the fraught nature of your arrival. You must forgive Stormward Baelgrim. Being suspicious is part of his directive. \n\nA formal discussion of our situation is warranted. If you wish to strike back at the nerubians, as we do, meet us at the Foundation Hall. Baelgrim and I need to review the data so far.\n\nIn the meantime, you are my guest. Take my ring. It will allow you to access Dornogal's amenities.", progress = "The attack seems concentrated on the Coreway. The rest of the city is secure, but we should ready ourselves for anything.", completion = "Baelgrim's vigilance has kept us safe all these years, but today we need help.", objectives = "Meet with various earthen citizens in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78458] = { id = 78458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Havrest Havoc - Activator" }
quests[78459] = { id = 78459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "State of the Union", description = "I hate to admit it, but we have been caught unprepared by the nerubians.\n\nOur processes focused on sustaining Dornogal and our declining population. \n\nStormward Baelgrim's stalwart pride has kept him and the Stormriders capable fighters, but they are already stretched thin, and they are not builders.\n\nThe Coreway's damage surpasses our ability to fix it.\n\nBut... that was not always so. I suppose if you wish to understand, you must learn more about us.", progress = "So much has been lost.", completion = "We are fractured in half. And now our purpose is being tested. Titans, give us strength...", objectives = "Learn from Merrix about the Council of Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78460] = { id = 78460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hypocenter", description = "I have failed my people. The Coreway is impassible. Dornogal's lifeline to the Ringing Deeps has been severed as has the path beyond.\n\nThe nerubians will get their comeuppance. It is my edict as it is my will.\n\nI will ascertain if the Councilward yet functions and bring him to the Archive. Speaker Brinthe should be there, titans willing.\n\nBut Oathsworn citizens are still in peril. If you wish to ally with us, clear the debris here and help our survivors. \n\nI will meet you at the Archive.", progress = "The Archive looks intact, fortunately. We must keep it that way at all costs.", completion = "You made it.\n\nGood.\n\nIs that a memory gem? You should not have disturbed our dead.\n\nBut... you have brought it to the right place.", objectives = "Clear debris and rescue earthen on the way to the Archive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78461] = { id = 78461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fourth Seat", description = "With me da' and Anduin weakened and Alleria nowhere to be found, it's up to us, {name}, to clear the way for Thrall an' Jaina's army if we hope tae strike back at the nerubians an' Xal'atath.\n\nBut we cannae get to the nerubians without the Coreway. An' we cannae repair the Coreway without the earthen's help.\n\nIf Merrix thinks this Adelgonn an' her \"Unbound\" are the only ones that can fix the Coreway, then we need tae find her.\n\nTime tae sharpen me smile an' put on me diplomat hat. Are ye with me, {name}?", progress = "If you are with Baelgrim, then the Council and Oathsworn must have accepted you onto our land.", completion = "It seems I have little choice but to hear you and Baelgrim out.", objectives = "Find Adelgonn in Freywold Village in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78462] = { id = 78462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Compassion", description = "The last thing I expected today was to see Baelgrim--much less receive his help. But I guess since the Coreway was damaged, he has no choice.  I... do not know how to compute this. It is only logical to accept it.\n\n<Adelgonn begins crushing the fungarian flesh roughly in her stone hands. It becomes a masticated pulp disturbingly quickly.>\n\nHere. Mix this with mud and apply it to the injured.", progress = "We've fought off animals and elementals before, but nerubians? My people are artisans and miners--not warriors.", completion = "<Adelgon appraises Moira, Baelgrim, and finally you.>\n\nI... thank you. It's been a long time since I've received help from outlanders--or the Oathsworn.", objectives = "Heal 5 Earthen denizens in Freywold Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78463] = { id = 78463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building Blocks", description = "The quarry is overrun with fungarians, all of the mining tunnels are collapsed, and we do not have time to clear them out and rebuild!\n\nHowever, I did spy a good amount of ore on the ground on the way here. It would be a start at repairing the Coreway but...\n\n<Baelgrim sighs and grimly looks at the injured Unbound earthen.>\n\nI am needed here. With Adelgonn's people. My people. Will you gather the ore in my stead?", progress = "Collect as much ore as you can. The Coreway is still my priority, but these injured need immediate help.", completion = "It is not much, but this ore should help stabilize the Coreway.\n\nWith Adelgonn's help, we will be able to reclaim the quarry and its mines and establish a supply line with Dornogal.", objectives = "Collect 20 Glittering Ore in The Orecreg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78464] = { id = 78464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delve into the Earth", description = "The nerubian attack, your meteoric fall...\n\nAnd now Baelgrim is here?\n\nBaelgrim needs more hands for his Coreway, but I couldn't help even if I wanted to. My people are dying as we speak. Some were abducted by the nerubians during the attack.\n\nYou're not the first outlander I've met. A small fellow, like Moira, arrived here earlier and wasted no time following the nerubians. He took the path west to a nearby cave.\n\nI would be in your debt if you found my people.", progress = "The mines were always dangerous even when the Stonebound worked them. Be careful.", completion = "Thank you for saving my people from the nerubians.", objectives = "Complete the Earthcrawl Mines delve near Freywold Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78465] = { id = 78465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golgrin's Reach", description = "Now that we have the opals, we can meet Brinthe in Golgrin's Reach.\n\nShe said there's a project she's workin' on there she wants me tae help with.\n\nI wonder what it is?", completion = "An archaeological site? A titan vault?\n\nBrinthe didna tell me about this!", objectives = "Meet Dagran at Golgrin's Reach in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78466] = { id = 78466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadows of Flavor - Activate" }
quests[78467] = { id = 78467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge for a Charge", description = "I am pleased Dagran has brought you here. I need help with a dangerous task.\n\nI used Dagran's opals to repair the titan console we recently recovered from this site.\n\nThe Oathsworn have long wanted to learn more about the titans and restore records unreachable in the Archive--or from before its construction.\n\nThis console may hold some answers if we can bring it back online.\n\nTake this device I have made. It will lead you to titan power cells we can use to power it on now that it is restored.", progress = "Without power, we will not be able to bring the console online.", completion = "Well executed, {name}.\n\nNow, I will need Dagran's help.", objectives = "Collect 3 Power Cells in Golgrin's Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78468] = { id = 78468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archive", description = "The memory gem you recovered is what its name suggests. It contains an earthen's memories, directives, and a hard coding of our Edicts.\n\nThis building, the Archive, is the nexus of our civilization. Here, memories are cycled, catalogued, and stored at the end of an earthen's scheduled rotation.\n\nWith the codex I have invented, we can access one or two memories from a memory gem. Take it, and read the memory gem you found.", progress = "The operating instructions are simple: insert the gem into the device, and a memory will play.", completion = "It is... comforting that Odon will be preserved in the Archive.", objectives = "Use the Prismatic Codex to view the Memory Gem. Then, return the Memory Gem to the Archival Repository in The Archive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78469] = { id = 78469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prairie Fever", description = "I was supposed to see Kodun earlier, but I'm as petrified as unliving stone. The attack on the village was... paralyzing.\n\n<Hreka takes a deep breath and focuses on the shape of another jar.> \n\nCould you do me a favor and deliver those jars to Kodun? He's a stone's throw away in the village pottery shop. I must finish this piece before the clay dries.", progress = "Are you one of the newcomers from the beach crash?", completion = "<Kodun turns the pottery over carefully.>\n\nPerfectly rounded, no cracks, a smooth lip... Hreka's done it again. She's our best crafter in town.", objectives = "Examine and then deliver Hreka's pottery jars to Kodun in Freywold Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78470] = { id = 78470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Proscenium", description = "The nerubians are attackin' the earthen again. We must follow that swarm!\n\nI fear we are outnumbered, but if the earthen can come together and stand with us...\n\nWe may just have a chance.", completion = "The wounded! The nerubians are kickin' the earthen when they're down.\n\n<Moira suddenly points to the center of the battlefield.>\n\nThere! In the middle... Is that Zirix? Again? And.. Alleria?\n\nOh, mountain's strength be with me... We've got tae help them, {name}!", objectives = "Journey to the Proscenium in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78471] = { id = 78471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convergence", description = "We know the nerubians are in league with Xal'atath. An' we have a fair idea why they attacked us--and Dalaran.\n\nThey seem bent on destroying the earthen--even kickin' 'em when they're down.\n\nBut why? Is it because the Coreway is the key an' destroyin' it was nae enough? Maybe what we're doin' here, repairin' the Coreway, is just what they dunnae want us to do.\n\nWe should go back to Dornogal an try to piece this together.", completion = "The earthen Council is reunited. Hopefully they can put the past aside an' get the Coreway repaired.\n\nThen hopefully they'll help us with the nerubians--an' Xal'atath.", objectives = "Return to Foundation Hall in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78472] = { id = 78472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glow In The Dark - Activate" }
quests[78473] = { id = 78473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Dreams, Lost", description = "You lost the Incandescent Essence? To be so careless with such a precious thing... I can grant you another.", objectives = "Awaken the power within the Fused Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78499] = { id = 78499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Citadel Sortie", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
