quests[78504] = { id = 78504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78508] = { id = 78508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[78529] = { id = 78529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Violent Impact", description = "<Your vision swims as you slowly regain consciousness. Distant shouts and screams echo in your ringing ears.\n\nThe last thing you remember is Dalaran, the great, floating city of magic, plummeting to the earth--then nothing but darkness.\n\nMixed in with sounds of shouting and battle, you hear a strange, insectoid chittering.\n\nThe nerubians were waiting for you.\n\nYou must rejoin the fight, but first you need to free yourself from the crushing weight of the rubble piled atop you.>", completion = "{name}! You survived!\n\nGood.\n\nKeep your weapons at the ready. This battle is just beginning.", objectives = "Climb out of the rubble and find your surviving leaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78530] = { id = 78530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay the Saboteurs", description = "The nerubians are everywhere, {name}.\n\nThere are too many for all of them to be solely crash survivors. I've seen others burrowing up from the ground. \n\nThis Queensguard Zirix was laying in wait here to overwhelm us.\n\nLet them know we are not easy prey. Cut them down!", progress = "We need to thin their numbers if we are to survive this.", completion = "Good work. And we've made progress as well. Perhaps now we can press forward.", objectives = "Kill 12 nerubians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78531] = { id = 78531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent Recovery", description = "We survived mostly unharmed. Not everyone was so lucky.\n\nMany who were in Dalaran when it went down are unaccounted for. They will need our help.\n\nSearch the battlefield for survivors. Help them in any way you can.\n\nWe need everyone up and fighting!", progress = "We must save everyone we can.", completion = "It is good to know many survived. \n\nWhen this battle is over, we will recover the bodies of those who did not.", objectives = "Aid 7 survivors of the Dalaran crash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78532] = { id = 78532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erratic Artifacts", description = "Dalaran housed many precious and powerful relics. Many of them were damaged in the crash and are now malfunctioning.\n\nThey must be destroyed!\n\nTake this scroll. I have stored a shattering spell within it. Read the words aloud and its magic will be unleashed.\n\nReport what you have done to Jaina when you are through. She will understand.", progress = "It pains me, but we have to destroy the malfunctioning relics!", completion = "Destroying more of Dalaran seems unconscionable.\n\nBut you and Aethas did the right thing.\n\nThey were unstable, and we could not risk their power being used against us.", objectives = "Destroy 5 Damaged Arcane Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78533] = { id = 78533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secure the Beach", description = "Queensguard Zirix emerged from the ground and surprised Magni.\n\nHe's near the farthest edge of the wreckage fighting off his swarm.\n\nMoira and I were trying to help, but we couldn't draw them away.\n\nCome with me. Magni needs our help!", completion = "You may not be trespassers, but you are not our allies either, outlander.\n\nIf you are to blame for the nerubians emerging, then you are responsible for the attack on Dornogal as well.", objectives = "Find Magni and defeat Queensguard Zirix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78534] = { id = 78534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Dornogal", description = "You have brought death and destruction to our shores the likes of which has not been seen in millennia.\n\nBut you have nerubian blood on your hands and a thraegar at your side. This is enough to earn my trust--for now.\n\nMy Stormriders and I must return to our capital, Dornogal, and investigate what is likely an ongoing attack there. Fly with us. Our slipstream will allow you to soar through the skies with ease.\n\nI will send other Stormriders to collect your allies once it is safe for them to land.", progress = "We need answers.", completion = "What have the nerubians wrought? And why?", objectives = "Meet Baelgrim in Dornogal by following the Stormrider's Slipstream.\n\nMost services in Dornogal will be unavailable during this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78535] = { id = 78535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Come from Below", description = "I do not yet know why you have come here, outlander. But you seem... efficient in killing nerubians.\n\nAs are we, the Stormriders, vanguards of this isle.\n\nThe nerubians are an ancient enemy. I would not be surprised if this Zirix knows and fears me, the Stormward.\n\nEven so, we could use your skill to help us protect Dornogal.\n\nI have a stormrook for you to ride. Mount up and help us rid our city of these insects!", completion = "I do not know why the nerubians have returned...\n\nOr why they would attack Dornogal.\n\nFor now I must focus on assessing the damage to the Coreway.\n\nOur brethren the Machine Speakers may need our aid, and it is the titans' will that the way to the center of Azeroth be kept open.", objectives = "Mount the stormrook Lokren and slay nerubians in Dornogal.\n\nMost services in Dornogal will be unavailable during this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78536] = { id = 78536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impossible Odds", description = "By the titans... The Coreway appears completely destroyed! It will take years, perhaps centuries, to remove the rubble and repair the damage the nerubians did to its inner structure, much less traverse to the world's core.\n\nMore than that with the Stonebound gone...\n\nI must take a moment to decide what to do.\n\nYour friends have safely arrived. Speak to them, and stay out of my way. \n\nIf we need you, I will let you know.", progress = "The Council must be appraised. There will be much to do...", completion = "My directive does not account for you, outlander.", objectives = "Speak to Thrall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78538] = { id = 78538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Group Effort", description = "The Unbound have arrived with the equipment and resources needed to begin repairing the Coreway.\n\nThis is a momentous occasion. One for the Archive! I would not say this to Adelgonn, but I see the titans' hands in it...\n\nAnd now it is time for me to exercise my directive! I have devised a plan for how to organize our workers most efficiently--and have also allocated supplies to welcome them.\n\nTake these orders to Adelgonn's workers so that they can begin in earnest. We will meet you there shortly.", progress = "We must begin work at once.", completion = "Even with this many workers, the Coreway's repairs will take time.\n\nWe need to decide what to do in the meantime.", objectives = "Distribute Merrix's orders to 10 Unbound Workers around the Coreway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78539] = { id = 78539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasting Repairs", description = "With my Stormriders... inactive, Dornogal is undefended, save a handful of lay peacekeepers. If the nerubians attack us here again, Dornogal will fall--and all of us with it.\n\nIt is imperative we draw them away from the city and take out their commander. \n\nWe can and will make our own web and capture Zirix in it.\n\nI have a plan.", progress = "We cannot remain on the defense.", completion = "Then it is settled.\n\nWe will make our stand at the Cinderbrew Meadery.", objectives = "Discuss the plan to attack the nerubians with Baelgrim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78540] = { id = 78540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Meadery", description = "Your archer friend is right. We must eliminate Zirix and his forces if the Coreway is to remain safe.\n\nLet us head to the Cinderbrew Meadery at once.", completion = "Thank the titans! The nerubians have not made their move to take the mead yet.", objectives = "Meet Baelgrim at the Cinderbrew Meadery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78541] = { id = 78541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lay the Trap", description = "With all these cinderbrew kegs here, this meadery would burn hotter than the Forgegrounds if they were all ignited.\n\nI surmise that's why Wenbrandt's kegs are made out of stout and strong ironwood--they do not break or catch fire easily. \n\nLuckily, we can start a reaction from the inside if we lead fuses into each of them.\n\nThose ropes the workers left around should work in a pinch.", progress = "We need to get the cinderbrew kegs prepared.", completion = "Zirix will fall by my hand. It is my directive. It is my will.", objectives = "Connect 4 Rope Fuses to Sizzling Kegs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78542] = { id = 78542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuation Area", description = "Look, you can blow up my life's work if it is our only choice, but I will not put my workers in danger.\n\nThis was the path we all chose, but I won't have them sacrifice themselves to fire or nerubians for it. Tell them that I said they need to get out of here immediately. \n\nAnd if a single one of them gets so much as chipped, the Council will have a lot to answer for!", progress = "If my workers cannot be kept safe, I am putting a stop to this plan.", completion = "I am glad to hear they had the sense to clear out without much of a fuss.", objectives = "Evacuate 8 Unbound Meadworkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78543] = { id = 78543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poking the Spider Nest", description = "The meadery is evacuated and the explosives are primed. It is time to bait the nerubians into our trap.\n\nYour compatriot is by the nerubian burrow north of here. She told me her directive is to keep watch over it in case the nerubians make a move before we are ready.\n\nSo far they have not made a move and may now need... coaxing. Take a keg of cinderbrew to the burrow. Tossing it in should stir their \"nest.\"\n\nRendezvous with us back at the Meadyard--quickly--after.", completion = "The nerubian swarm is on its way.\n\nPrepare yourself.", objectives = "Throw a Keg of Cinderbrew Mead into the nerubian burrow and then return to the Meadyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78544] = { id = 78544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Thunder", description = "The nerubians will strike out in anger and pride--which is exactly what we want.\n\nThey will swarm the meadery soon, seeking to punish us for attacking their burrow. We will hold them here on the ground while you take to the skies. When Zirix appears to command his army, we will light the fuses.\n\nWenbrandt scrounged together some supplies we can use to corral the nerubians. Set them up quickly, and then we will get you on a stormrook. Go!", completion = "Zirix is dead. We did it. It is over. Baelgrim did it.\n\n<She repeats the last phrase to herself over and over more quietly each time as if unable to process the event.>", objectives = "Hold off the nerubians at the Cinderbrew Meadery until Queensguard Zirix appears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78545] = { id = 78545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Coreway", description = "We dealt a heavy blow to the nerubians. But Baelgrim...\n\n<Adelgonn pauses to compose herself.>\n\nHe was infuriatingly rigid and we argued ceaselessly, but in the end... he was a defender of our people--all of them.\n\nBaelgrim sacrificed himself to vouchsafe the Isle of Dorn from the nerubians. Everyone needs to know that--and we can't let the nerubians force our hand like that again.\n\nGo back to Merrix in Dornogal. Tell him we will come soon. We just... need a moment here.", progress = "How fares your sortie at the meadery?", completion = "You are alive! But what of the others?", objectives = "Return to Merrix in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78546] = { id = 78546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recompense", description = "We heard the echo of the explosion from here.\n\nI presume you have found victory, but your solitary arrival suggests not all is well.\n\nWhat happened?", progress = "Tell me what happened.", completion = "May we all learn from Baelgrim's valor.\n\nHe died to preserve our people--our unity. We must not let that be in vain.", objectives = "Speak to Adelgonn to inform Merrix of Baelgrim's fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78555] = { id = 78555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underground and Overwhelmed", progress = "Dead nerubian skitterlings, unexploded bombs, injured workers... what a mess.", completion = "Thank you for getting the workers on their feet. You've restored order, or at least enough for us to get back to work.\n\nThe best way to impress Foreman Uzjax is by getting work done, and you're doing that.\n\n*whispers* ... but tread carefully. He's loyal to the powers that be, so we should watch what we say.", objectives = "Help Machine Speakers secure Ironhaul Station.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78557] = { id = 78557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Off Track", description = "Speaker Brinthe acknowledged. Outlanders, there is work to do.\n\nOne of our larger mine carts has derailed. It's blocking the station's main junction. \n\nMy workers' productivity is impaired, and their functioning is suboptimal. The titans put us here to work, but my workers aren't all working. Could you go and get us back on track?\n\nBe careful. I can see you're made of flesh and bone. I don't want you to be crushed.", progress = "As long as we stay loyal, hit our deadlines, and meet our quotas, everything will be fine. \n\nThe gears keep grinding, and we keep working.\n\nPraise the Machine.", completion = "Report requested. Did you find anything? \n\nIt's a what? A \"skar-dyn\"? \n\nThis information is irrelevant to my assignment. Focusing on work.", objectives = "Investigate the derailed mine cart in Ironhaul Station.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78558] = { id = 78558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazar Spree", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78559] = { id = 78559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazar Spree - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78560] = { id = 78560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazar Spree - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78562] = { id = 78562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discarded and Broken", description = "You there! You're here to help, aren't you?\n\nThe humming melody of the machines is changing, and I... I admit I am not ready. For so many years I served faithfully, and then...\n\nWell the important thing is that I'm ready to get to work again. But you see, my tools have all been broken and scattered about. \n\nIf you could keep an eye out for them and bring them back to me, I would be in your debt.", progress = "A machinist is nothing without the tools of office.", completion = "My gauge! My calipers! My wrench!\n\nIt feels good to have them in my hands again. Though, I have to admit, I have not been entirely honest with you.", objectives = "Collect Machinist Kittrin's lost tools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78563] = { id = 78563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weight of a World", description = "My tools didn't randomly end up where you found them. They were placed there. By me.\n\nI had reached a point so low that I saw no alternative. The machines, the great work of my people, were never going to sing again. So why should I bother to keep them repaired?\n\nBut now I see, and now, I understand!\n\nThe last tool I need, I dropped it into the water, and it was eaten by a giant creature. I think that one might need a bit more force to return it to me.", progress = "Once I have all my tools back, I know that things will be right again.", completion = "<Kittrin doesn't seem bothered at all by the intestinal goo that coats the calibrated weight.>\n\nYou found it! Now let me get this cleaned up, and the rest of the tools repaired. Then, I will be ready to serve once again.", objectives = "Collect Machinist Kittrin's Calibrated Weight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78564] = { id = 78564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforged Purpose", description = "That's all of them! Now, it's time to do my duty and recast these tools. Reforge them, and myself, into what I was meant to be: a proud machinist of the Ringing Deeps.", progress = "I'm ready to do my part once again. I just need to reforge these old tools.", completion = "I can't thank you enough for all of your help. I lost my faith, but now, I have both my faith and my tools back.\n\nI'm forever grateful to you.", objectives = "Help Machinist Kittrin reforge and rededicate the tools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78565] = { id = 78565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getaway to Scenic Grizzly Hills!", description = "Today's special is a magical getaway to the majestic forests of Northrend!\n\nSay, you're one of those adventurers, right? Listen, I need a favor.\n\nCould you pick me a few flowers from Grizzly Hills? I've got my hands full here, but there's someone I'd really like to give a bouquet to.", progress = "My partner would really appreciate these flowers.", completion = "Thanks a bucket, {name}!\n\nI hope you enjoyed your trip in the hills! Everywhere you look, there's something new to discover.", objectives = "Take the Scenic Getaway Portal to Grizzly Hills to pick a bouquet of flowers for Gabbo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78570] = { id = 78570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frayed Legacy", description = "Keep true, {race}t.\n\nWe of the Woldguard uphold an ancient promise to Freya to tend to these lands. Our edict is older than those wielded by the demagogues in Dornogal. Older than Dornogal itself.\n\nHowever, not all lands have been tended equally. The leader of our order was to care for the basin nearby but we've not heard from them in many cycles.\n\nI have sent a novice to investigate. Aid them and my order will be in your favor.", completion = "This is not as this basin should be. We have much work to do.", objectives = "Meet Igris at the Boskroot Basin on the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78571] = { id = 78571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mycomayhem", description = "Freydrin was the leader of my order. I was sent here to assist them. I was too late.\n\nThere is a darkness that haunts these woods, {race}s.\n\nThese woods were Freydrin's home. It was her charge to tend to them, so given by the Keeper herself. And now she is gone and her woods run amok.\n\nBring me the spores of these mayhemic menaces. Perhaps there is a way to cleanse this land yet.", progress = "Do you have them all?", completion = "Thank you, {name}. I will take a close look at them. The fungarians of these woods pose a greater danger than any of us anticipated.\n\nWe must be prevent their spread.", objectives = "Collect 30 Boskroot Spores from fungarians in Boskroot Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78572] = { id = 78572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wold Memories", description = "Freydrin must have had some way of fending off the fungarians.\n\nAlthough there are few left in the countryside who still follow the Edicts, Freydrin was long a true believer. She would never have allowed these woods to reach this state while she held faith.\n\nWe should take a look at her home in the woods. Perhaps there is something that may prove useful inside.", progress = "Looking through the Woldkeeper's things unnerves me. So many untold stories.", completion = "This staff holds a familiar magic I had hoped to forget. Oh Freydrin, what happened here?", objectives = "Search Freydrin's home for help against the fungarians in Boskroot Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78573] = { id = 78573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper's Aid", description = "Magical staff? Wards? What were you doing, Freydrin?\n\n<Igris ruminates briefly, her brow crinkling and eyes aglow. After a moment, she turns to you with a smile carved into her face.>\n\nI've got it! \n\nThe life energy in this staff should overcome any mycotic corruptions in the wildlife here. Then you return them to the natural cycle and the land will heal on its own in time.\n\nAnd if you see any wards, take them down. Take her memory gem just in case. It may yield more information yet.", progress = "There is much latent magic buried within this staff. It may be our only hope to bring these fungarians to heel.", completion = "Simply fascinating.", objectives = "Use Freydrin's Shilelagh to purify Boskroot Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78574] = { id = 78574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boss of the Bosk", description = "There is one final thing I must ask of you.\n\nThere is a great monster that roams these woods. I am certain you've sensed it. It must be felled.\n\nRotbark was Freydrin's final means to control this basin, but even this was too great for any individual earthen. Ours is not to control, but to tend to its needs.\n\nUse the staff once more and bring an end to Rotbark's reign.", progress = "If we are to restore this place, we must do so a different way. We must carve a new path.", completion = "Rotbark's demise will mark the ending of this basin's deterioration.\n\nThank you, {race}. Your assistance has been most invaluable.", objectives = "Defeat Rotbark the Unfelled in Boskroot Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78579] = { id = 78579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", objectives = "Your assistance has been paramount in revitalizing the Dream. Please accept this as a reward for your efforts. Thank you for all your hard work, champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
