quests[78589] = { id = 78589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasive Cuisine", description = "<This rarely seen plant may be of use to Chef Dinaire.>", completion = "Umbral Eggplant might not be everyone's idea of a delicious food, but when I prepare it, it is a crowd favorite!", objectives = "Deliver the Umbral Eggplant to Chef Dinaire at the Fungal Fields.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78590] = { id = 78590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Edge" }
quests[78591] = { id = 78591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getaway to Scenic Nagrand!", description = "Today's special is a magical getaway to the great plains of Nagrand!\n\nIf you're headed there, would you mind shooting a few animals? Oh, not like that! Here, borrow my camera.\n\nMy friend Beatrice has been roaming around there lately. She would really appreciate some photographs, but I've got portals to attend to.", progress = "There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", completion = "I knew Beatrice would appreciate your photographs.\n\nThank you for your kindness, {name}.", objectives = "Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Beatrice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78594] = { id = 78594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getaway to Scenic Feralas!", description = "Today's special is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited!\n\nUnfortunately, some of the partygoers who took this portal earlier left their gifts here at the gala.\n\nCould you help me return them? Meet me at the beach and we'll figure out which gifts belong to whom.", progress = "There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", completion = "Thanks for the assistance, {name}! You've made a lot of people happy by getting their gifts back to them.\n\nAnd what an array of gifts they were! Maybe the language of love looks different to everyone.", objectives = "Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78595] = { id = 78595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream Infused", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, your deeds have helped garner enough strength for a dream infusion! Meet me at the Central Encampment so I can get it to you.\n\n- Elianna", completion = "Infuse away!", objectives = "Talk to Elianna in the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78596] = { id = 78596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons to Lord Greymane", description = "Greetings, \n\nLord Greymane has requested your presence at Stormwind Harbor to assist him with a matter regarding Gilneas.\n\nThat is all I am able to say.\n\nGood luck, {name}.", completion = "{name}, thank you for coming.\n\nLet me brief you on the mission.", objectives = "Meet with Genn Greymane at Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78597] = { id = 78597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clandestine Movements", description = "{name},\n\nLilian Voss and Calia Menethil have requested your presence for a clandestine operation involving Gilneas.\n\nThey will brief you in full when you arrive.", progress = "Excellent, we've been waiting for you.", completion = "{name}, thank you for coming.\n\nLet me brief you on the mission.", objectives = "Meet with Lilian and Calia in Pyrewood Village in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78598] = { id = 78598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream Infusion", objectives = "Your contributions have helped us harness enough power for another Dream Infusion! Great work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78600] = { id = 78600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amirdrassil, the Dream's Hope: Up in Smoke", description = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", progress = "The energy found within these fragments will allow us to quickly access the Throne of the Firelord.", completion = "These should grant us access to Smolderon's throne more easily.", objectives = "Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Normal difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78601] = { id = 78601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amirdrassil, the Dream's Hope: Up in Smoke", description = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", progress = "The energy found within these fragments will allow us to quickly access the Throne of the Firelord.", completion = "These should grant us access to Smolderon's throne more easily.", objectives = "Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78602] = { id = 78602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amirdrassil, the Dream's Hope: Up in Smoke", description = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", progress = "The energy found within these fragments will allow us to quickly access the Throne of the Firelord.", completion = "These should grant us access to Smolderon's throne more easily.", objectives = "Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78607] = { id = 78607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Mereldar", description = "We must get to Mereldar and let General Steelstrike know what the Order of Night tried here.\n\nThank the Sacred Flame we stopped them before they could do any worse.", completion = "Finally, a chance to rest.", objectives = "Travel to Mereldar and meet with General Steelstrike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78608] = { id = 78608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geothermal Jaunt", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78609] = { id = 78609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geothermal Jaunt - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78610] = { id = 78610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geothermal Jaunt - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78613] = { id = 78613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bastion of Hallowfall", description = "I have to admit, I did not think that the first visitors we'd have in Mereldar would have been outsiders. I thought the Empire... Well, nevermind.\n\nYou have been more than helpful to my people, and that deserves recognition. Mereldar is the bastion of the Arathi in Hallowfall. Take some time, rest.", progress = "This city has much to see.", completion = "It's been good to sit down and breathe for a bit.", objectives = "Explore Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78614] = { id = 78614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mereldar's Light", description = "I still need more time with Alleria to learn about Xal'atath. What I have learned is very worrying.\n\nFaerin sent word that she was going to the orphanage, and asked you to meet her there. \n\nShe often entertains the children while she is in Mereldar, I don't doubt she would appreciate you doing the same.", progress = "It's great to see how happy these kids are, after what they have gone through.", completion = "I love coming here whenever I visit Mereldar. The kids always bring a smile to my face, and I hope I do to them as well. \n\nAfter everything they have been though, they deserve happiness.", objectives = "Play with 3 Arathi Orphans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78615] = { id = 78615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bell Tolls", description = "Those bells mean Mereldar is under attack! \n\nLet's get to the gates and find out what is going on.", completion = "We will make them pay for this, {name}. \n\nWe will hit them so hard they never come back.", objectives = "Go to the main gates of Mereldar in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78616] = { id = 78616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technoscrying: The Mysteries of the Concord Observatory" }
quests[78618] = { id = 78618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Frenzy" }
quests[78620] = { id = 78620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crossroads of Twilight", description = "We need to take the Veneration Grounds back from the kobyss. \n\nPush them back and pave a bloody path through them.\n\nWe need to stop whatever is happening at the Eternal Flame! If they manage to corrupt it like they did at the tower... I don't even want to imagine what will happen.", progress = "Flames, they just keep coming.", completion = "Now we just need to deal with the shield.", objectives = "Kill 15 kobyss attackers in the Veneration Grounds in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78621] = { id = 78621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Rising", description = "I can sense three beacons of void ahead, all funneling their power into one massive font of darkness.\n\nYou will need to kill them. With them dead, I can bring down the shield.", progress = "I'm ready to end this.", completion = "Excellent. \n\nNow to break through this shield.", objectives = "Kill the kobyss deepspeakers in the Veneration Grounds in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78624] = { id = 78624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Candle in the Dark", description = "Beledar has turned to Shadow, we must retreat back to Mereldar!\n\n<Vaelisia looks towards Aelric Leid.>\n\nI-- No. We need to destroy Aelric first.\n\nTake him down, then we retreat.", completion = "May the Light bless Faerin. \n\nI thought the Eternal Flame lost. \n\nI thought this was the end of hope, and the death of our people.", objectives = "Kill Aelric Leid in the Veneration Grounds in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78626] = { id = 78626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spar Day", description = "Your skills in combat are impressive, {name}. \n\nWe are rotating our next round of reserves into active duty, and they need to sharpen their skills. \n\nWhile Alleria fills me in on Xal'atath, I would appreciate it if you could help with their training.", progress = "The tricks they learn from you today will help them survive a difficult encounter later.", completion = "Thank you.\n\nWhat they learnt from you will no doubt save their lives later.", objectives = "Duel 8 Arathi Recruits in Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78627] = { id = 78627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Front", description = "Just before the kobyss attacked, we received word of a disturbance near Livia's Patience. Now we know the cause.\n\nWe... Light... We can't survive fighting on two fronts, {name}. We have to stop this, now.", completion = "Flames, they tunnelled up through the lake bed.\n\nLivia's Patience has already fallen.", objectives = "Travel to Light's Redoubt in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78628] = { id = 78628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapdoor Sprung", description = "We need time to get the Reckoning ready. Take your friends and hold back the nerubians for as long as you can.\n\nThey deserve nothing but death for what they have done to our people.", progress = "How goes the hunt?", completion = "Good job, {name}. I'm surprised the nerubians aren't fleeing already!", objectives = "Kill 15 nerubians in Livia's Patience in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78629] = { id = 78629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running on Reserves", description = "We have to try to save any of our people left alive in Livia's Patience. \n\nEvery Arathi is or was a member of the military. If you can help them, they'll be able to help themselves.", progress = "I managed to rescue a few, did you find people to rescue?", completion = "Thank you, {name}. Between myself, Alleria, Anduin, and you, I think we managed to save quite a few. \n\nThe nerubians abducted many of the rest. We need to help them!", objectives = "Assist 5 Arathi Reserves in Livia's Patience in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78630] = { id = 78630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Reckoning", description = "The Reckoning is ready!\n\nLet's make these spiders pay. Blood for blood.", progress = "We will make the nerubians regret ever thinking they could push into our home!", completion = "What fools we are.", objectives = "Board The Reckoning and slay 150 nerubian forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78631] = { id = 78631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking to the Speakers", description = "I've heard about a problem nearby, and I think I know what's wrong.\n\nWe used to have a mining operation northeast of Gundargaz. When we moved out, kobolds moved in.\n\nWe haven't heard from those kobolds in a long time, but it sounds like they're raiding us now! And the High Speaker is doing nothing about it.\n\nSomeone has to do something. If we can solve this, more Machine Speakers will listen to us. If the High Speaker doesn't get results, we will.", completion = "It's good to see some of the kobolds are not so keen on this war.", objectives = "Reassure Gundargaz' defenders on the way to the Lost Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78634] = { id = 78634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Stone Behind", description = "Many earthen fell when the kobolds took this mine.\n\nWorse, those who fell were left to crumble where they dropped. There was no attempt to recover them. We couldn't provide closure or respect their memories. Why? Why did we forsake the fallen?\n\nWe will not fail them again, {name}. Gather the identification plaques of those we lost, so we may commemorate them properly.", progress = "Have you found them?", completion = "Thank you, {name}. The fallen will be remembered.\n\nThe earthen above us have their own rituals of remembrance, and the Machine Speakers have procedures in place. \n\nThere's a plinth in the town square with the plaques of the fallen. Jurlax will ensure that the proper observances are performed... along with process checks and a recalculation of worker allocation. Work never stops here.", objectives = "Recover Identification Plaques from fallen earthen in the Lost Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78635] = { id = 78635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death and Waxes", description = "Kobolds take candles seriously. Wax, even more. More important than gold. More important than freedom!\n\nWe steal candles from Candle King. We make him look weak. Bully that looks weak loses control. Gets dead!\n\nAlso means we not have to wait out here in dark until get eaten. Hurry!", progress = "Did you take candle?", completion = "<Skitter visibly relaxes in the presence of the candles.>\n\nAh, good. Now get me out of this!", objectives = "Recover Flickerflame Candles from around the Lost Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78636] = { id = 78636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retaking the Mines", description = "Now that we have the keys, it is time to take the fight to the Candle King.\n\nGet that gate open. Once we're inside, we'll move on to the next step.", completion = "That...did not go as expected.\n\nOur new kobold friend might have some better ideas.", objectives = "Unlock the gate to the Lost Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78637] = { id = 78637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracking Cogchewer", description = "Cogchewer is muscle for Candle King. So mean! Rebuilds earthen gears for wars. Also in charge of mine's defenses. \n\nNeed his keys to get in the mines... and get me out of this thing!", progress = "Did you find keys?", completion = "Thank you, {name}. Never thought I walk free again.", objectives = "Kill Cogchewer in the Lost Mines and recover his keys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78638] = { id = 78638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engineering Destruction", description = "Some of the kobolds are retrofitting equipment left behind when the mines fell.\n\nPlease, destroy the rigs before they're used against us. I'd rather they be scrap than in the hands of an enemy.\n\nThere was a storage depot on the western edge of the lowest level of the mine. Start there.", progress = "Are any still operable, {name}?", completion = "Thank you. Our enemy now has one less advantage.", objectives = "Destroy mining rigs in the Lost Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78639] = { id = 78639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ko-boldening", description = "Bullies everywhere!\n\nInnocent kobolds kept down by Candle King's thugs all across Warrens.\n\nGive bullies taste of own medicine!\n\nOnce bullies beaten, innocent have chance to run. Be free!", progress = "Now they will see what it feels like!", completion = "Is start, friend. Is start. Thank you.", objectives = "Free oppressed kobolds in the Warrens by defeating their captors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78640] = { id = 78640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manifesto Destiny", description = "Before take mines, my people live in great city. Stoneheads call it the Warrens.\n\nCandle King's bullies run it now. We need see what we are fighting. Let kobolds know we here to help! Better choices than Candle King.\n\nWhat better way than pamphlets? Everyone love pamphlet! We draw real good!\n\nBrinthe say you have some sort of flying dragon-bird-thing? Perfect for scout! Perfect for dropping pamphlets!\n\n<Skitter looks at you expectantly, making small flapping motions as she waits.>", progress = "Never flown before. Is fun?", completion = "Sad to see home in such state.\n\nBut we fix!", objectives = "Scout out and distribute pamphlets across the Warrens from the air.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78641] = { id = 78641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tackling Torchsnarl", description = "Torchsnarl runs Warrens for Candle King. Nothing but big bully! Very, very big bully.\n\nWe show everyone. Bullies can be beaten!", progress = "Torchsnarl is big one. Don't know why hiding behind flunkies. Still, can't miss him!", completion = "Sad he got away, but everyone else? See him as coward! Just as good.\n\nI'm tall, so I use words good. He's huge! He should use words gooder! Not very smart.", objectives = "Defeat Torchsnarl in the Warrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78642] = { id = 78642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Candle, New Hope", description = "We weaken Candle King's grasp. Still need symbol, rally my people.\n\nKing has ancient relic: symbol of hope. Called Candle Crown. Heart of my people. Candle King threw away! Found new prize: Darkflame Candle.\n\nThat crown? Still in hoard. Candle King should come out now. See what we did here!\n\nWhile he looks, we sneak in! Use old tunnels! Take what's ours! We smart.", progress = "We take hope from darkness, {name}.", completion = "Ha! We did it! Everyone knows now: Candle King is not only way.", objectives = "Recover the Candle Crown from the Darkflame Cleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78643] = { id = 78643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fair Skies and Strong Winds", progress = "The Dragon Isles stand in your debt.", completion = "Fair skies and strong winds to you, {name}.", objectives = "Speak with Alexstrasza at the Seat of the Aspects in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78645] = { id = 78645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: Buried in the Riverbed" }
quests[78646] = { id = 78646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Watch", description = "My mother seems unable to fully attune with the Eye. Perhaps it senses her ties to Ardenweald...\n\nHer shield is but a fraction of the Eye's power. If she was fully attuned, she could completely quench our foes' flames.\n\nBut we cannot idly wait. We still need more information about Galok and his plan of attack. Bodwin indicates there is new flurry of activity in Igira's base of operations. With Bodwin's help, we can investigate without being seen.", completion = "This will not be easy...", objectives = "Regroup with Merithra at the edge of Eye of Ysera, overlooking Slagfell Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78649] = { id = 78649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: Something Big Beneath the Riverbed" }
quests[78655] = { id = 78655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adaptive Cooling Salve", description = "Should you need my assistance, I can craft you an ointment that should prove helpful in your attunement with Fyr'alath.\n\nBring me the materials I don't have, and I'm sure I can put something together.", progress = "Keep at it. All this hard work is going to pay off.", completion = "Perfect.", objectives = "Bring ErdenZaralek Glowspores, Awakened Frost, and a Dreaming Essence for the Adaptive Cooling Salve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78656] = { id = 78656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hose It Down", description = "With the flame restored, you can see the extent of contamination to the fishing hole. Kobyss and frogs have left heaps of strange goo that pollutes the shoreline.\n\nWe need your help to clean up this gooey blight! \n\nI have a specially modified harvester equipped with a water barrel. Use this device to spray water on the goo piles and clean the shore of this contamination.", progress = "Have you cleaned up the shoreline?", completion = "Great work {name}, things will be a lot less messy around here now!", objectives = "Activate Baeny the Barrel and use the hose to wash away 40 Contaminating Goo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78657] = { id = 78657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Midnight Sentry" }
quests[78658] = { id = 78658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hallowed Path", progress = "Who are you?", completion = "Friendly outsiders are not common in Hallowfall. Only enemies emerging from the shadow. \n\nBut you seem comfortable in the light despite how unusual you may appear. I would welcome you, were we not in the midst of a crisis.", objectives = "Meet with the denizens of Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78659] = { id = 78659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Light Touches", description = "Many in Hallowfall will call you \"outsider\". I would call you friend. I would also ask for your help, if you are no stranger to combat. Desperate times forge strong friendships.\n\nGeneral Steelstrike ordered the army to fall back from the nerubian onslaught. In doing so, she abandoned a Lamplighter and many troops to the darkness. I may not be able to save them on my own, but with your help I may succeed.\n\nIf you're willing, ride with me or meet me there.", completion = "Outsider! The nerubians took us by surprise. The army went into retreat when the wall was breached. I've been keeping them away from this tower, but I could certainly use your help.", objectives = "Meet with Faerin's ally near the Aegis Wall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78661] = { id = 78661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: Treasures in the Cliffside" }
quests[78662] = { id = 78662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: A Cliffside Full of Caches" }
quests[78663] = { id = 78663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: Scattered Around the Tower" }
quests[78664] = { id = 78664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift of Self-Care", description = "The eyes of a tired adventurer.\n\nA {class} that does many great deeds for many people. When was the last time you did a kind gesture for yourself? \n\nPerhaps now is the time. Look into your heart. \n\nWhat do YOU desire?", progress = "Love is a blessing, especially if it comes from within.", completion = "Let us begin your journey to self-love.", objectives = "Speak with Ying to discover your heart's desire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78665] = { id = 78665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tunnel Trouble", description = "It's good to have new allies here. Together, we have much better chances of protecting this tower.\n\nThe nerubians have overwhelmed us. If we're going to have any chance against them, we need to destroy the burrows they're using to come under the Wall.\n\nIf you can handle that, we will survey the field from the top of the wall and meet you there.", progress = "Were you able to stop the nerubians from coming under the ground?", completion = "Excellent, {name}--if we don't have to worry about the nerubians stabbing us in the back, we can deal with those pouring through below.", objectives = "Destroy 6 Nerubian Burrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78666] = { id = 78666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Good Spider", progress = "{name}, every nerubian you kill here could mean a life saved in Hallowfall, and aids the chances of our own success.", completion = "This is a good start. There are still many more nerubians coming from below, but we must turn our attention to those already inside Hallowfall.", objectives = "Kill 12 Nerubian attackers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78667] = { id = 78667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekindled Memories", progress = "Have you recovered their tinderboxes? Every life deserves to be remembered in the Sacred Flame.", completion = "Thank you, {name}. You've helped to honor their sacrifice as well as we can.", objectives = "Recover 6 Arathi tinderboxes from fallen soldiers and burn their bodies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78668] = { id = 78668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally on the Dawnbreaker", description = "It's critical, with so many nerubians pouring through the Aegis Wall, that we defend our airships docked at Tenir's Ascent.\n\nThe nerubians have always outnumbered us, but our fleet allows us to concentrate our defenders where they are attacking, as well as allowing us to bombard them from the safety of the skies.\n\nIf we lose our armada, our hopes fade dramatically. Meet us there when you can.", completion = "I'm glad you're with us, {name}. \n\nWithout our airships, we have little chance of holding back the nerubians in the long run. \n\nTo say nothing of our dockworkers, who are safe below deck.\n\nLet's see to the defense.", objectives = "Meet Faerin at Tenir's Ascent aboard the Dawnbreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78669] = { id = 78669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Their Eyes Only", progress = "Have you found any of those shadecasters yet, {name}?", completion = "Final war? Ascension? Not as many answers as questions, {name}. But we at least have some pieces of the puzzle.", objectives = "Gather 3 nerubian Shadecasters to learn their plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78670] = { id = 78670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege Weapon Sabotage", progress = "Were you able to destroy their siege weapons, {name}?", completion = "With those siege weapons destroyed, we're in much better shape. Faerin went ahead to light the Dawntower with Great Kyron. She asked that we meet them there.", objectives = "Destroy 4 siege weapons below Tenir's Ascent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78671] = { id = 78671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light of the Dawntower", completion = "Just in time, {name}--Beledar has fallen dark for a time. But now we have our own light to hold back the darkness.", objectives = "Assist the Lamplighters in lighting the dawntower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78672] = { id = 78672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lamplighter's Duty", description = "Darkness has fallen. We can't rest yet. \n\n<Faerin gives you a weary smile, but there is a light in her eyes.>\n\nThe light from the tower will hold the worst dangers in the darkness at bay. It's my duty, as a Lamplighter, to keep all the towers blazing. \n\nMy patrol takes me to Lorel's Crossing by air next. I would welcome you and Anduin at my side, for all our sakes.", completion = "The kobyss have already been dragging innocent villagers to the shore! They'll drown them and eat them!\n\nWe have to save them!", objectives = "Take the Lamplighter Skiff to Lorel's Crossing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78674] = { id = 78674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift of Relief", description = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. \n\nI saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress. \n\nPerhaps he has insight to teach you.", progress = "I've seen men die of stress. You don't want to bottle it up every day.", completion = "Feeling better?\n\nYou must take care of yourself after a tough day. If you're good to your body and brain, they'll be good to you.", objectives = "Speak to Simeon Griswold at the Gala of Gifts, then relieve your stress in Old Town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78679] = { id = 78679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift of Relaxation", description = "Self-love can take many different forms. And on occasion it can take the form of relaxing. \n\nThe night elf by the fireworks seems particularly relaxed. \n\nPerhaps you could ask him for his insights on relaxation.", progress = "True love is letting your guard down. Let yourself relax, you will see what I mean.", completion = "You feel renewed, don't you? Personally, I love petting the turtles.\n\nDid you discover your favorite relaxation technique?", objectives = "Speak with Bordol Dewgarden about relaxation, then relax by Olivia's Pond in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78685] = { id = 78685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tunnel's End", description = "So we're hearing more rumors about Taelloch. \n\nThe town and its mine are responsible for ore production. Apparently, we haven't received shipments in weeks, and the town's foreman has disappeared. Now the High Speaker is discouraging anyone from traveling there.\n\nThat tells me we should investigate. And of course, if people are hurting, then we should help them.", progress = "We have to find out what happened here.", completion = "Beasts inside?\n\nThe residents of Taelloch might need our help.\n\nHelp me keep an eye on Dagran, {name}. He's read a lot of stories about thrilling adventures, but he hasn't seen what we've seen. \n\nAnd something seems... off.", objectives = "Investigate the rumors about Taelloch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78686] = { id = 78686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lights Out", description = "Name's Aegor. I try to keep tabs on Lamplighters in the field and assess what areas of Hallowfall may be in need of their aid.\n\nThe dawntower fell dark at Velhan's Claim a few weeks ago. Based on what's been happening around Hallowfall, it's probably because of the rising tide of kobyss.\n\nLamplighters Taenar and Aemyra are heading there, but this might be more than even two Lamplighters together can handle. Will you meet them there and help them restore the light at Velhan's Claim?", completion = "Pleased to meet you, {name}. I'm Taenar, and this is Aemyra.\n\nThe dawntower at Velhan's Claim went dark a while ago, and with all that's been happening, we're only just getting here to help.\n\nWe did some scouting, and it seems the area is overrun with kobyss. I imagine Velhan's holed up inside, instead of fighting them off.\n\nGood thing for his people that we're here. And it's better still to have you along helping.", objectives = "Meet Taenar and Aemyra near Velhan's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78687] = { id = 78687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crash Recovery", progress = "Did you find those tinderboxes, {name}?", completion = "The flame burns for us all, {name}. I wish I could have saved them that night, but I'm glad we'll be able to honor their memories.\n\nIt's what we all would want, if it happened to us.", objectives = "Retrieve 4 Recovered Tinderboxes from the Indomitable's stalwarts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78688] = { id = 78688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cage, Match", description = "When we were scouting before you arrived, we saw a lot of cages set up around Velhan's Claim. Typically, the kobyss use these to hold their victims until they're needed for a ritual sacrifice.\n\nThose sacrifices lead to... lots of other dark activities. Not the least of which is eating the victims.\n\nLet's get ahead of all that. Take my torch, and destroy the cages, so we don't have to see that happen to anyone from Velhan's Claim.", progress = "Have you dealt with those cages yet? The citizens of Velhan's Claim won't be safe until you do.", completion = "Good work, {name}. Without their cages, the kobyss won't be able to take prisoners.\n\nNo prisoners means no foul rituals, and preventing those gives us a much better chance of saving the people at Velhan's Claim.", objectives = "Burn 10 kobyss cages with Aemyra's Holy Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78689] = { id = 78689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If It Leads, It Bleeds", progress = "Did you find their leaders? They look strong, but I'm sure you're up to the task.", completion = "Excellent. That will put us and the kobyss on a more even footing. At least in terms of leadership.\n\nThey still outnumber us by a lot, but one thing at a time.", objectives = "Defeat the kobyss leaders besieging Velhan's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78690] = { id = 78690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Situational Awareness", progress = "It's so important to reassure the citizens of Velhan's Claim, {name}, that they'll get through this. Hope is everything in dark times.", completion = "We're here to help. But I've learned in the past, that there are times hope and reassurance can be the most urgent need.\n\nWhile you were talking with the residents, Taenar and I have determined what our next steps are going to be. \n\nWe need to give the people room to breathe, but we also need to prepare them to fight.", objectives = "Speak with 10 citizens of Velhan's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78691] = { id = 78691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The One That Got Away", progress = "Stay focused, {name}--we have to find my son.", completion = "I know it sounds trite, {name}, but I could never thank you enough for getting Max home safely.\n\nThrough all this, you've also shown me I need to be out front, leading the way for my people. I've seen there are outcomes worse than death. \n\nI can't undo the mistakes I've made in the past, but I can be certain not to repeat the pattern.", objectives = "Rescue Maximillian at the crash of the Indomitable.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78692] = { id = 78692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teach a Man to Fish", progress = "Have you handed out those spears yet? The people need them to remind them what they're capable of.", completion = "I think now we'll see them acting very differently, now that they're armed, {name}.\n\nThere's something about knowing you can take care of yourself, that you can handle your own problems, and you don't need anyone to rescue you.\n\nOf course, we Lamplighters will always be there to help, but it's very likely that we won't be needed next time.", objectives = "Distribute 8 spears to the residents of Velhan's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78693] = { id = 78693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spears for Fears", progress = "Kobyss giving you trouble? Soon, the people of Velhan's Claim will be the ones giving them trouble.", completion = "Good work, {name}, this is exactly what we need to not just drive the kobyss back today, but to make sure the people of Velhan's Claim can defend themselves in the future.", objectives = "Gather 8 Kobyss Spears for the people of Velhan's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78694] = { id = 78694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Velhan's Claim", progress = "How's it going out there, {name}? You sending those creatures of darkness back to the deeps?", completion = "You know, I've hated the kobyss ever since they were dragging my fellow stalwarts into the night as dinner guests.\n\nHopefully because of the work you've done, that won't happen to any of the citizens of Velhan's Claim, {name}.", objectives = "Kill 12 Kobyss warriors around Velhan's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78695] = { id = 78695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lamp Lit", progress = "Did you get those torches set, {name}? The people will be able to quickly light them whenever Beledar fades.", completion = "You saved my son, {name}. You broke the spine of the attack on our home, gave us what we need to fight. \n\nYou helped me to be the leader I'd pretended I was. Thank you.\n\nThe Lamplighters will always have allies in Velhan's Claim.", objectives = "Place 8 torches around the perimeter of Velhan's Claim, then observe the re-lighting of the dawntower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78696] = { id = 78696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Don't Go to Taelloch", description = "This troubled Machine Speaker was here to do something. But what? It looks like something really did some damage to him.\n\nWe shouldn't dally. \n\nWe need to head into Taelloch and look for the foreman. Can you clear the entryway into the town? Someone could get hurt!", completion = "There's not much to see in the foreman's office. If we want answers, we'll need to search the town.", objectives = "Clear the entrance to Taelloch of encroaching beasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78697] = { id = 78697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghost of a Company Town", description = "The foreman isn't here. Obviously. But the evidence points to her being here recently. So perhaps she's still nearby!\n\nWe should go further into town and see if anyone has any idea where she might be.\n\nOr maybe someone else can give us the answers we need. Maybe we'll find out on our own! Maybe it was some sort of attack or some kind of... sorry. I'm getting ahead of myself. Let's go investigate!", completion = "Well... there's one question answered perhaps. Only to unearth a dozen more.", objectives = "Use the Investigate ability to find clues about what happened in Taelloch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78700] = { id = 78700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Controlled Demolition", description = "I know we've fought skardyn before, champion, but this... this is worse. \n\nI knew that skardyn were turning earthen into more skardyn, but I didn't expect... the crystals... the spikes... the roiling blue energy... that smell! Anyway, not what I expected at all. \n\nIf we must venture out there, I'm taking down some of those abominations along the way.", progress = "There's more to be done. We can't let this corruption spread.", completion = "Maybe we've only killed a few skardyn from a much larger swarm. But we have to start somewhere.", objectives = "Kill 18 skardyn in Taelloch", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78701] = { id = 78701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truth in Chalk", description = "So the people of Taelloch use chalk on slate to leave messages to each other. So many clues! But what does it all mean....\n\nI'm seeing a pattern, and I think it points to the mines. If the workers haven't already been lost, I'd expect them to be in the mines.\n\nAnd I know the foreman is the key. She has to be.", progress = "There's more to learn here. I'm sure of it.", completion = "I think I know where we need to go next.", objectives = "Search for messages in Taelloch Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78703] = { id = 78703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried in Stone", description = "We need to go into the cave, the one mentioned near the last slate. It's not signed, but I think that's the foreman's handwriting... and we've looked everywhere else. We have to investigate.", progress = "We're missing something... There must be something in that cave!", completion = "I knew it! I was right! There's something in here. Something someone was trying to hide.", objectives = "Investigate the cave at the back of the Taelloch Mine", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78704] = { id = 78704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Foreman", description = "Dagran was right. I suppose I shouldn't be surprised by that any longer.\n\nAll the signs suggest there's something in this cave. Maybe the foreman is hiding here. Maybe she can give us some answers.\n\nWe've come this far. Let's see what's inside.", progress = "There must be answers deeper within the cave.", completion = "That was her. The foreman. It had to be. After all that... she was already gone.", objectives = "Find the foreman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78705] = { id = 78705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What She Saw", description = "What is that? That thing the skardyn dropped before we... before it died.\n\nI think I've seen something like that before.", progress = "I think I know what that gem is...", completion = "Oh. This is bad, isn't it?\n\nThe foreman witnessed this conspiracy at the Hall of Awakening.\n\nThen she traveled back to Taelloch with her memory gem.\n\nShe tried to warn the others, but she was infected... and her transformation was swift. She sealed herself in this cave, but her corruption still spread.\n\nAnd the High Speaker knew what would happen. The High Speaker is behind all of this!\n\nWe've got to warn Brinthe. We've got to warn the world.", objectives = "Investigate the gem left by the skardyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78706] = { id = 78706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Speaker's Secret", completion = "Thank you for looking into the mystery plaguing Taelloch.\n\nWhat did you find?", objectives = "Return to Brinthe in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78713] = { id = 78713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Within", description = "There is a vision being seen across Azeroth. A \"Radiant Song.\" We believe it's a warning, but we are unsure of its meaning.\n\nMeet me in Silithus. We must ask Azeroth's Speaker what this vision means.", completion = "We're all here. Good. Let's find out what the Radiant Song is trying to tell us.", objectives = "Go to Silithus to talk with Thrall about the visions spreading across Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78714] = { id = 78714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Poor Reception", description = "There's strong evidence that the Radiant Song is a warning from Azeroth herself. A cry for help.\n\nThat's why we're here. If this vision truly is Azeroth's message, Magni will know what she's trying to tell us.\n\nHe should be in the Chamber of the Heart. Let's go.", completion = "I know why you're here. It's the visions. Azeroth's voice, heard all across the lands. Ye thought I would know what she's trying to tell us. \n\nWell, ye thought wrong.", objectives = "Go to the Heart Chamber to ask Magni for help deciphering the Radiant Song.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78715] = { id = 78715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeroth's Voice", description = "I haven't spoken with Azeroth for years. At first I just didn't feel the need. Then I realized I had started to resent her. For leaving me like... this. And now I'm not sure if I can.\n\nBut I know the stakes. This Radiant Song of hers foretells something dire. And we need to know what.\n\nFirst, we need to prepare the Heart Chamber. Can ye start up the consoles nearby?", progress = "I understand Magni's concerns, but we have no other choice. The future of our world is at stake. We must try everything we can to understand what Azeroth is trying to warn us of.", completion = "This has never happened before. Magni is the Speaker of Azeroth. Why would communing with her cause him to collapse?", objectives = "Help Magni perform his ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78716] = { id = 78716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Painful Lessons", description = "Magni appears stable for now, but he's still not responsive. We need to get him treatment quickly. I'll open a portal to Dalaran.\n\nFollow us when you can.", completion = "I'm unsure why the Speaker of Azeroth would end up in such a state after attempting to... well, speak with Azeroth.\n\nAll we can do is wait for Magni to recover.", objectives = "Take the portal to Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78717] = { id = 78717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mysterious Warning", description = "Well, that was quite the nap. I wasn't expecting Azeroth to be so... loud. To normal folk, she's gently calling out. But with our connection, it felt like she was screaming. Directly into my crystal noggin.\n\nI saw it though. Khaz Algar, an island of earthen, bathed in fire and smoke. That's where Azeroth is trying to lead us.\n\nThat's what we need to protect.", progress = "Khaz Algar...", completion = "The council has decided. We travel to Khaz Algar.\n\nDalaran will teleport as soon as we're able. Will you lend us your aid in our preparations?", objectives = "Discuss the next steps, then follow up with Khadgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78718] = { id = 78718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strengthen the Wards", description = "Magni's vision foretells that Khaz Algar may be enduring some... turbulent times. And so it is best to ensure that Dalaran is ready for the worst.\n\nHere, take this wand. It's been attuned with Dalaran's defense magics.\n\nJust wave it near strategic parts of the city to strengthen our magical defenses.", progress = "We will be hard pressed to save Khaz Algar if our own defenses aren't strong enough to withstand attack.", completion = "Well done, champion.\n\nLet's just hope it's enough. I would hate for anything to happen to our city right as the world needs us most.", objectives = "Strengthen Dalaran's defenses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78719] = { id = 78719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Citizens of Dalaran", description = "Our citizens must be prepared for Dalaran's departure. Can you ask around the city and see if anyone requires aid?\n\nI'd also like for you to speak with Brann and Archmage Drenden. They both had concerns that would be best to address before we depart for Khaz Algar.", progress = "Dalaran is always ready to defend the world, but that doesn't mean we can do so on a whim. Preparations are key to a smooth transportation.", completion = "Thank you for your help. It's important that the citizens of Dalaran are ready for whatever may come.", objectives = "Help the citizens of Dalaran prepare for the teleportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78721] = { id = 78721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Team", description = "If we're going tae be exploring new lands in Khaz Algar, then we'll be needing help from the Explorers' League. But they won't be alone in this adventure. The League is teaming up with the Reliquary again, just like on the Dragon Isles. \n\nThey're calling themselves the Algari Expedition this time around.\n\nI'm just a wee bit worried if they're still getting along. Exploring can tear folks apart just as easily as it binds them together. Can you check in on the lot?", progress = "A league and an expedition walk into a tavern... Nope, nothing's coming to me.", completion = "They're getting along? Well I'll be a goat's uncle. Ach, no offense to Dagran.\n\nWell, that certainly makes my job easier. Thanks for checking in on them, all the same!", objectives = "Check in on the Algari Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78722] = { id = 78722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Khaz Algar!", description = "From what Magni has seen, Khaz Algar may not be the safest of destinations. We'll be relying on your aid, should a fight break out.\n\nLet me know when you're ready to depart.", completion = "She was Archmage Drenden. All along, Xal'atath has been watching, plotting, right in front of me. How could I be so blind? \n\nAnd now she's invading Dalaran with an army of nerubians. \n\nXal'atath planned this. All of this. She wanted us to come to Khaz Algar.", objectives = "Tell Khadgar you're ready to depart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78724] = { id = 78724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loving Yourself, Your Way", description = "If it's a challenge you're after, I think I have an idea.\n\nI saw a boastful champion heading toward Goldshire. You could challenge him to a duel.\n\nThis would satisfy your desire and perhaps teach him a valuable lesson in humility.", progress = "How fares your challenge?", completion = "On any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all.", objectives = "Defeat Matley Graston in a duel near Goldshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78726] = { id = 78726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loving Yourself, Your Way", description = "A full belly is a happy belly!\n\nThere is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", progress = "Have you had your fill of treats? I love the fruits, myself.", completion = "On any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all.", objectives = "Consume treat packages from vendors at the Gala of Gifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78727] = { id = 78727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loving Yourself, Your Way", description = "While visiting this gala, I am staying at the Lion's Pride Inn at Goldshire.\n\nI hear they have some extra beds upstairs. Why not see if you can sleep there for a while?\n\nI think I will have a bit of a rest too... Right... here...", progress = "<Ying is quietly snoring.>", completion = "...Huh? Oh! Welcome back, did you enjoy your rest?\n\nOn any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all.", objectives = "Take a nap in the upstairs guest room at the Lion's Pride Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78729] = { id = 78729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising a Stink", description = "Those clues add up to an ugly story, {name}.\n\nThat map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic.\n\nI've got a guy that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.", completion = "There you are, right on time.\n\nI've got a plan to deal with this chemical conspiracy.", objectives = "Meet Inspector Snagglebolt at the entrance to Shadowfang Keep in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78738] = { id = 78738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absent Speaker", completion = "The High Speaker and his followers will answer for their crimes.", objectives = "Meet Speaker Brinthe in the Earthenworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78739] = { id = 78739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: The Trove in the Tower" }
quests[78741] = { id = 78741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sympathetic Speakers", description = "I have to stop the High Speaker from making more skardyn.\n\nMachine Speaker protocol dictates that one of the foremen in this area should have a key to the Hall of Awakening. Come with me, and we'll track it down!", completion = "This should get us into the Hall of Awakening...", objectives = "Look for Machine Speaker Foremen in the Earthenworks with Speaker Brinthe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78742] = { id = 78742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of the Earthenworks", progress = "I'll admit: the ability to acquire an army at the drop of a hat has gotten me fairly far in life.", completion = "You've managed to drive out some of the High Speaker's most devoted disciples... and you've cracked some heads.\n\nThat's a fine start. But there's so many... too many...", objectives = "Defeat enemy Machine Speakers, constructs, and help frightened workers in the Earthenworks!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78743] = { id = 78743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before I Depart", description = "I can feel my energy reserves depleting.\n\nI will soon not be able to execute my duties. That is why I have Urtago here to take over.\n\nBefore my systems grind to a halt, I must make sure Mourning Rise is free of kobolds. They have invaded the memorial site I tend and plunder the Unbound shrines and bodies that are there.\n\nMaybe it is good you are here. You may have the strength to help us.\n\nPlease, help Urtago rid the site of kobolds.", completion = "Korgran still calls himself the caretaker, but I'm the one who has been taking care of Mourning Rise for some time.\n\nI don't mind. Korgran is very kind. \n\nBut the situation here has gotten away from me. We have some work ahead of us.", objectives = "Meet Urtago at the Mourning Rise memorial site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78744] = { id = 78744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Their Memories", description = "Take these gifts and place them by the past caretakers. Each is a gift honoring their memory.\n\nI'd also like us to perform some light groundskeeping to at least maintain the site. Unfortunately, what these kobolds are doing to the memorials will take us weeks to fix.\n\nPlease do what you can about the kobolds. It would be unwise to leave the gifts unguarded while they are still roaming the area.", progress = "The kobolds cannot be left to desecrate Mourning Rise.\n\nThe Unbound that rest here are here because they do not want to be disturbed or moved. While they do not wish to be revived, taking their armor and possessions is an insult to earthen culture.\n\nWe must do something.", completion = "I am amazed how much damage the kobolds have done to the site. So many shut-down earthen desecrated!\n\nI know that I am not yet the head caretaker, but I take full responsibility for this. I should have asked for the mantle of caretaker long ago when Korgran started to show the first signs of memory overwrite and stasis lock.", objectives = "Eliminate the kobold infestation and place gifts near the shut-down, past caretakers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78745] = { id = 78745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You No Take Plunder!", description = "It looks like the kobolds have taken gems and other... body parts off these shutdown earthen. \n\nAbominable.\n\nFind where the kobolds are holding their plunder, and bring it back to me so I can return it to its rightful place later.\n\nThis vandalism will not go unchecked!", progress = "Were you able to find their plunder?", completion = "Thank you for doing this.\n\n<Urtago nods to herself with confirmation as she examines the items.>\n\nI am relieved, but there is much more work to do.", objectives = "Recover earthen belongings from piles of plunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78746] = { id = 78746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laws Apply to All", description = "Desecrating a memorial site is one of our greatest taboos in earthen society. This site is a window to our past, into our memories, and a place of self-reflection where we can commune with those who are no longer here.\n\nStill, so many of these kobolds infest Mourning Rise. For their crimes, the kobolds deserve the harshest punishment. They must be culled even further.", progress = "So many of them still infest Mourning Rise.", completion = "I was not made as an earthen of the sword, nor as one who calls for violence. That is the domain of the Stormriders. \n\nWhat these kobolds did is frowned upon not just by us, the Unbound, but by everyone in earthen society. I am not proud that we had to kill them, but we had to stop them by any means.", objectives = "Slay kobold invaders in Mourning Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78747] = { id = 78747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Collapse", description = "Now that we landed a mighty blow, it is time to make sure that we block their tunnels so they cannot come back.\n\nRemember the stuff that Korgran asked about? Explosive sticks--his recipe. I have brought enough to shake a mountain! More than enough for the kobolds.\n\nHelp me show these kobolds that we will fight for what is ours so they will never come back!", progress = "Is it done? Were the tunnels dealt with?", completion = "Ha ha! What did I tell you? I felt the tremors from back here!", objectives = "Use the Explosive sticks to destroy Kobold tunnels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78748] = { id = 78748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting the Wick", description = "Knowing kobolds, they will have several workmasters, or leaders, running this raid.\n\nFind and eliminate these so-called \"workmasters.\" The rest of them will get disorganized, forget why they are here, and hopefully leave us alone.", progress = "Were you able to slay all three of them? Their deaths will strike a significant blow to this kobold operation.", completion = "Eliminating the minds behind this operation will only buy us more time if and when the kobolds decide to do this again.\n\nUnfortunately, there is still one more kobold brain that we have missed. Until now.", objectives = "Find and slay the kobold workmasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78749] = { id = 78749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Runs This Fine Establishment?", description = "While you were dealing with the tunnels and the workmasters, I saw a peculiar kobold go into a cave to the northwest. The kobolds seemed to respect him more than the others, calling him Grand-Heister Bokk and offering him the food you call \"cheese.\" This makes me think he is the real mastermind.\n\nIf that kobold is in fact the real Ward of this operation, then we should take the opportunity to strike him down.\n\nI will meet you at this cave.", completion = "I am happy to see you, {name}.\n\nI feel my inner workings grinding--that's a sign of anxiety. Korgran nears his shutdown with every passing moment, and then this place will be under my care. \n\nIt is a lot of responsibility. But I believe that I am ready for it.", objectives = "Slay Grand-Heister Bokk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78754] = { id = 78754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Delivery", description = "<You find a small yet heavy leather-bound package on the road with an attached label.>\n\nGundargaz Courier Express\n\nEXPEDITED\n\nTo: \nHarvester Farnee\nDurgaz Cabin\n\nOPEN WITH CARE: Contains volatile elemental minerals.", completion = "Well, smoke the hive... you found it! I still can't believe the courier just lost my package...\n\nWe've been waiting on this to help with Shalehoof's leg. \n\nMixed with fire honey, this stuff should patch him up quickly!", objectives = "Deliver the Abandoned Package to Harvester Farnee at Durgaz Cabin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78755] = { id = 78755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing in the Mud", description = "Remember when we used that clay and the fire honey to patch up Shalehoof? Let's do that again but bigger!\n\nProblem is we've run out of clay. But fortunately, with all the recent seismic activity, a whole avalanche of elementals has been roused out of torpor and are clashing on the eastern beach!\n\nBring me wet, elementally charged silt to use as our restorative substrate!", progress = "By combining living sand and water, we can create an elemental silt that mimics the underclay's healing properties. Or at least something that comes close to it!\n\nIsn't elemental fusion fascinating?", completion = "Can you feel the energy in the silt between your fingers, {name}? The charge that hums through it?\n\nIsn't it exhilarating? Doesn't it make you feel one with the earth and the mountains?", objectives = "Gather 20 handfuls of Elementally Charged Silt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78756] = { id = 78756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lots and Lots of Fire Honey", description = "If Harmot wants to patch this sleeping boulder up and get him out of my pond, I'm all for it. \n\nUnfortunately, we used the last of my store of fire honey on Shalehoof's wound. I haven't had time to harvest any from the Cinderwold with all these elementals running amok. \n\nHead on down to the wold's edge and bring us some honey. You're going to need a lot.", progress = "Mind yourself in my forest. Cinderbees are dangerous, but we rely on them for the honey they produce for our mead.", completion = "You found this off of WHAT? A living honey e--\n\n<Farnee stops her sentence before lowering her voice.>\n\nLet's keep all mention of living fire honey between us. Harmot might get distracted and run off into danger if we tell him...", objectives = "Find a lot of Fire Honey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78757] = { id = 78757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honey and Clay the Pain Away", description = "Ramoliths! Magnificent, aren't they? One of the finest elemental beasts on the isle. \n\nThe bad news is they're not immune to injury. Poor Shalehoof here was attacked by awakened elementals in Farnee's pond.\n\nThe good news is that we have all we need to tend to him.\n\nWe just have to mix that clay you found with some fire honey and slap it up on ol' Shalehoof's hock! \n\nReady?", progress = "Much like us earthen, healing something made from rock and stone is no easy task.\n\nBut the unique properties of the clay you've brought, combined with the fusing properties of the honey makes for an excellent restorative!", completion = "Well, aren't you just a natural with the elements. Ever thought about making a career out of it?\n\nSay, since you're not afraid of getting messy, why don't you help us with Farnee's problem?", objectives = "Help Harmot prepare Shalehoof's salve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78758] = { id = 78758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulse Within the Earth", description = "Before we go and wake up a slumbering mountain giant, it's probably best we get an idea for how deeply asleep he is. \n\nThough, if the nerubians burrowing up didn't wake him up, I'm not sure what will.\n\nTake these earth shards and plant them on the waterfalls and hills around the lake. \n\nOnce we've got them set up, I'll be able to get a reading on the giant's health.", progress = "Once you've got the shards set up, I can drop the final one here to get a proper read.", completion = "The mountain giant's got a weak heartbeat.\n\nPoor lad's likely been disturbed from a deep slumber with all of these elementals breaking off from the falls.\n\nFortunately, the pair of us are experts in healing elemental and elemental-adjacent's life forms, aren't we? \n\nIf the salve can work on earthen and rock rams, it can work on mountain giants!", objectives = "Place 4 Tremor Stones around the pond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78759] = { id = 78759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Wake a Giant", description = "By the Coreway, this stuff packs a punch!\n\nCombining healing silt with the molten fusion properties of fire honey has given us a salve that could wake a whole mountain!\n\nWhich is exactly what you'll do. Take the mixture over to our wounded friend in Farnee's pond, and slap it on his hide!\n\nIt should be enough to wake him up and alleviate any soreness.\n\nHopefully, anyways.", progress = "This will either wake the giant and patch him up good as new or...\n\nWell, let's not talk about the other possibility. Have some faith in the process!", completion = "Well, would you look at that! \n\nThousands of years slumbering at the base of a waterfall and he wakes up without even a roar or a foot-stomp.\n\nHah! And Farnee was worried!\n\nYou did great with making that salve, {name}. Both Farnee and I owe you a big thanks. \n\nOur new friend looks thankful too!", objectives = "Apply elemental salve to the mountain giant for Harmot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78760] = { id = 78760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron from Above", description = "We've done our best to contain the High Speaker's followers. We've hampered their efforts at destroying or looting anything they can take with them into Hall of Awakening.\n\nNow, we just need to deal with the leader of their forces before they can coordinate a more unified resistance.\n\nAre you ready to do this, {name}?", completion = "The Ringing Deeps should be safe... for now. But the High Speaker...\n\nWe need to follow Speaker Brinthe into the Hall of Awakening.", objectives = "Defeat Supervisor Varric and his forces within the Earthenworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78761] = { id = 78761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Machine", description = "No time to catch our breath! The High Speaker is fleeing to the earthen's most sacred machine. We need to follow him.\n\nRemember, we're doing this for the earthen! For justice! For all the brothers and sisters and comrades who've fallen to the High Speaker's hubris!", completion = "He's gone? He really gone?\n\nAs far as I'm considered, he just abdicated his authority. I don't know where he fled, and I don't care. Now that the Awakening Machine is operational again, we can step up and set things right.", objectives = "Confront the High Speaker inside the Hall of Awakening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78762] = { id = 78762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Find", description = "We've got a find on our hands! Looks like this might be one of my books from undergrad. Hah!\n\nNow, your job is to get all that dirt off of it, but you have to be careful. The artifacts we handle are very fragile, and the only thing worse than them staying in the ground is them breaking on the way out.\n\nEmpowering your elemental will only get you halfway. You'll need to use your environment to keep things in balance so that it's safe to excavate.", progress = "What do you think? Having fun yet?", completion = "There you go! Your first artifact... of a kind anyway.\n\nThe stuff we find out in the field is usually more exciting. But at least this one you can keep as a souvenir!", objectives = "Practice excavating on the Outdated Geology Textbook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78763] = { id = 78763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[78764] = { id = 78764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[78765] = { id = 78765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[78766] = { id = 78766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[78767] = { id = 78767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[78789] = { id = 78789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flightstones" }
quests[78820] = { id = 78820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technoscrying: The Mysteries of Igira's Watch" }
quests[78821] = { id = 78821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blooming Dreamseeds", description = "The Emerald Dream is about the harmony and balance of nature. For Amirdrassil to bloom, we need a rich variety of plants growing alongside the world tree. Plant seeds wherever you find fertile soil.", progress = "How's the planting going?", completion = "Thank you! It's in these many small acts that allows the Emerald Dream to flourish, and thus nourish Amirdrassil.", objectives = "Plant dreamseeds in the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78827] = { id = 78827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Take Candle!", description = "Ksk, ksk! You there! Yes, you!\n\n<You hear the sound of jostling behind the vent and a new, even scratchier voice emerges.>\n\nWe, er, I have job for you! You look sharp. Look quick. Fast hands, just like us--me! Quick hands just like me.\n\nBring us, me, bring me candles! Yes! \n\nNo ask question, just go get candles. \n\nWe are, er, I am professional, yes. Professionals do not ask questions. \n\nOnly get candles.", progress = "You have candles?", completion = "<Exuberant chanting can be heard from within the vent.>\n\nCandle! Candle! Candle!\n\nHush! Shh! Don't let the stone ones hear...", objectives = "Steal candles for the suspicious vent in the Gundargaz Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78837] = { id = 78837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pomp and Dire Circumstance", description = "I'm seeing legitimate concerns. We have to do something about the nerubians... even if the High Speaker won't. If he won't do something, I will.\n\nThe High Speaker sent me to the surface because I wasn't \"reasonable.\" I think we should have a chance to... reason... with him. We'll need to go to Gundargaz.", progress = "That is... never pleasant.", completion = "So much for reason. \n\nThe Ringing Deeps has plenty of problems, and the High Speaker is obviously distracted. He sounds obsessed! \n\n{name}, if you and your companions can help us solve some of our challenges here, maybe I can convince the Machine Speakers to help you against the nerubians. That's a problem that concerns us all.", objectives = "Meet Speaker Brinthe in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78838] = { id = 78838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cogs in the Machine", description = "Gundargaz is my home. Or at least, it was before the High Speaker saw fit to reassign me above ground. I've missed my home, but it's... changed.\n\nAs the number of Machine Speakers decreases, we're in a race against time. \n\nLately, we've been especially weary of our assigned tasks, but as always, we must bear our burdens.\n\nLet me show you around the area. There are some earthen I would like you to meet.", progress = "This is not how I remember my home.", completion = "Problems are increasing, and our numbers are dwindling.\n\nThe High Speaker is distracted, kobolds are attacking, shipments are missing from Taelloch, and earthen aren't returning from their shifts.\n\nWhere to begin? Looks like our work is cut out for us.", objectives = "Accompany Brinthe as they talk to earthen in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78839] = { id = 78839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold Shoulder", description = "The first step to stemming our losses and retaking the mines is straightforward, if unpleasant. Without minions, this Candle King will be less of a threat to Gundargaz.\n\nSee if you can reduce the swarm, {name}, before hostilities escalate further.", progress = "This should never have happened.", completion = "Grim work, but necessary.", objectives = "Kill invading kobolds in the Lost Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78860] = { id = 78860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Candles!", description = "I, er, we...no, no, I! I have new deal for you, oh shadowy one. \n\nMore candles! \n\nIn return, you get... er...\n\n<Frantic shuffling reveals a new voice.>\n\nYou get more candles! Then you give to us! To me! \n\ncandles! candles! candles!\n\n<The excitedly whispered chanting continues for some time.>", progress = "You have candles? More candles?", completion = "Ksk! You did it!\n\nMore candles...\n\n...unlimited candles.\n\n<A somber awe emanates from the vent.>", objectives = "Steal more candles for the suspicious vent in the Gundargaz Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78861] = { id = 78861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord" }
quests[78863] = { id = 78863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Place Beneath the Boughs", description = "Thanks to you and all the mortals who defended the Emerald Dream, a new World Tree now grows in the Dragon Isles.\n\nAmirdrassil's boughs will be a haven of peace and tranquility, and a place of respite for the kaldorei souls lost at Teldrassil.\n\nTyrande Whisperwind and Shandris Feathermoon are at the tree now. They would share words with you.", completion = "Welcome to Bel'ameth, {name}.", objectives = "Meet Tyrande and Shandris in Amirdrassil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78864] = { id = 78864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning", completion = "My father has returned to us at last, {name}!", objectives = "Speak with Shandris Feathermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78865] = { id = 78865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siblings Until the End", description = "Some time ago, Vyranoth received an unexpected summons... from Iridikron.\n\nYou will want to hear what he had to say.", progress = "Iridikron had much to say...", completion = "I know not what Iridikron intends to do next. But I can no longer call him \"brother.\"", objectives = "Speak with Vyranoth to hear about her meeting with Iridikron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78866] = { id = 78866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superbloom: Step 2" }
quests[78867] = { id = 78867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superbloom: Step 3" }
quests[78868] = { id = 78868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superbloom: Step 4" }
quests[78869] = { id = 78869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superbloom: Step 6" }
quests[78870] = { id = 78870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superbloom: Step 7" }
quests[78871] = { id = 78871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superbloom: Step 8" }
quests[78874] = { id = 78874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conjured Help", description = "If you're looking for food--softy food--I'm afraid we're clean out. Nothing but good ol' rocks and gems here at the moment.\n\nIt's starting to become a problem, actually.\n\nSay... you wouldn't be able to do anything about that, would you? Rustle us up some victuals for the fleshy folk?", progress = "You don't want to try a nibble of cobalt?", completion = "Strike me with a hammer and call me an anvil--that's a lot of food!", objectives = "Summon food for Innkeeper Brax in the Gundargaz Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78875] = { id = 78875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unkillable", description = "I'm bettin' dat ogre Mai'Zoth is behind all dis. He should have died long ago, but his magics still be strong. \n\nHe be using the altar's centerpiece as a conduit to drain Lukou's power.\n\nRecover the centerpiece and prove he's not so unkillable when he doesn't have a loa hostage.", progress = "Did you prove Mai'Zoth isn't unkillable?", completion = "That centerpiece be critical. It was being used to drain Lukou directly.", objectives = "Recover the altar centerpiece from Mai'Zoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78876] = { id = 78876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Glowing Memento", description = "<An unusually persistent ember draws your eye. It glows with a pure, primal heat.> \n\n<Vyranoth would be interested in this.>", completion = "An ember of primal flame, somehow untouched by the shadowflame of that wretched cavern... \n\nThank you. It is a warm reminder of the brother I had long, long ago.", objectives = "Bring the Everglowing Ember to Vyranoth in Amirdrassil or the Central Encampment in the Emerald Dream.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78877] = { id = 78877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bless These Homes", description = "Divine presence acknowledged.\n\nEvery day for as long as my memory serves me, I have walked the routes and lit the incense around our homes. It has ground my joints to dust, but is it an important task. \n\nA sacred task. \n\nThese are dark times we live in--perhaps you could add your own beatitudes to our little rituals?", progress = "You do us an honor, bringing your faith into these caverns. Let it bless these machines and those who work with them, just as they bless us in turn.", completion = "We are all cogs in the machine. We turn, and turn, and turn... \n\nThere is a beauty there. \n\nA quietude.", objectives = "Bless the incense around Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78879] = { id = 78879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evoking the Forge", description = "Harumph! This blasted forge is on its last legs. We'd repair it, but Stonemason Itsak picked up a shift at Ironhaul Station when the Coreway collapsed, and well...\n\nThere's no one to fix it anymore.\n\nIf you can figure out a way of getting it running hot again, Gundargaz would be in your debt!", progress = "I'm going to miss Itsak. He made the best end-of-shift rock roasts...", completion = "Whoa! I've never seen anything like that! You just... keep fire in your throat?\n\nNow that's a trick I'd been keen on learning!", objectives = "Find a way to stoke the forge outside of Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78880] = { id = 78880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Kingdoms Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, skyrider!", objectives = "Visit Lord Andestrasz in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78881] = { id = 78881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Kingdoms Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, skyrider!", objectives = "Visit Lord Andestrasz in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78890] = { id = 78890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Frenzy" }
quests[78892] = { id = 78892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superbloom: Step 9" }
quests[78893] = { id = 78893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scrap of Bronze", description = "The vendors of Pandaria do not want the equipment you will find in this timeline.\n\nYou can convert unwanted equipment into Bronze using the magic of the infinite dragonflight.\n\nUse the Unraveling Sands ability and scrap the Unraveling Tunic.", progress = "You can place unwanted equipment into the Unraveling Sands to obtain additional Bronze for your journey.", completion = "Bronze can be spent at infinite bazaars to upgrade your equipment, acquire gems, or expand your collections.", objectives = "Use the Unraveling Sands ability to summon Unraveling Sands, then place the Unraveling Tunic in the Unraveling Sands to scrap it into Bronze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78894] = { id = 78894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Growth", objectives = "If you bring me sufficient Bronze, I will empower your equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78895] = { id = 78895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shadow Over Gundargaz", description = "You look dangerous.\n\n<Toki spits on the ground.>\n\nThat's good. We need dangerous. Something is stalking Gundargaz. \n\nSomething mean. \n\nSomething... recent. \n\nJust before the Coreway collapsed I started getting reports of workers going missing mid-shift. Only thing we've been able to find have been the odd chunk of rock.\n\nFingers, mostly. \n\nIf you could sniff out what's stalking my town, I'd be in your debt.", progress = "Life didn't always used to be this exciting.", completion = "A demon? Escaped from the crashed ruins of a flying magical city?\n\nIf you say so. \n\nI'm just glad it's sorted.", objectives = "Track down whatever is hunting the earthen in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78897] = { id = 78897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom or Blight", description = "This place is infested with cave borers. They pose a threat to the great roots that stretch through this place.\n\nYes, the tree provides sustenance for many living things, but this is not some small band of bugs nibbling on a leaf. This is a blight. Their numbers must be culled for the good of the whole. \n\nBy my oath I am unable to raise a hand to interfere. However... you have sworn no such oath. Will you do what must be done?", progress = "How fares the blight?", completion = "You have my gratitude, stranger.", objectives = "Cull 10 worms of the Wormlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78898] = { id = 78898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intention vs Instinct", description = "Cave borers are not social creatures as a rule. Seeing this many gather in one place speaks to intention.\n\nA wormcaller of the nerubians must be present.\n\nFind them and recover the tool they use to call these worms here. With it we can lead them away in time.", progress = "I can sense more worms coming. As if they are drawn to this place.", completion = "What a strange gem. \n\nThe song within must be what is drawing the worms to this place.", objectives = "Collect a Singing Stone from Wormcaller Iz'tikrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78900] = { id = 78900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Cold, Dark Wings", description = "You came down the Coreway, right? From up top?\n\n<Toki chuckles.>\n\nThey have it easy, those city earthen. Down here, death comes for you from all around. \n\nFrom below. From above.\n\nYou look like you've killed a fair few beasts in your time. Care to add another to the list?", progress = "Keep quiet, that's my advice.", completion = "The monstrous bat wasn't quite so monstrous after all, eh?\n\nWelcome to Gundargaz.", objectives = "Track down the Ringing Death in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78901] = { id = 78901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heeeelllp!!!", description = "Hey! You!\n\nGet me down! Away from these worms! Please!\n\nI'll pay you! I'll even owe you one! Heck, I'll gladly sell out any cartel member you need dirt on! \n\nJust get me down!\n\nAlso, don't walk too much. They can hear your footsteps. Move from rock to rock if you don't want a swarm coming after you.", completion = "Okay, okay! I'm okay.", objectives = "Rescue Skedgit Cinderbangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78902] = { id = 78902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delegated Dig", description = "Okay, I know when I'm beat. So I want to hire you as my Champion of Coin... or coinchamp.\n\nThis is all a part of my brilliant enterprising venture. See, these worms here are great at rooting out rich minerals like a niffen sniffing out high-quality mushrooms. \n\nI'm willing to bet all of my money--and your life--that they found a vein of sivstone. Great stuff, though I doubt a {class} would know how to use it. \n\nTell you what, you bring me a shipment's worth and I'll go halfsies on the profits with ya!", progress = "You get the goods?", completion = "Nice haul! This should get us started back in Mmarl and show those goons who's who. \n\nHere's your cut.", objectives = "Acquire 25 Chunks of Sivstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78915] = { id = 78915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squashing the Threat", description = "I need your help!\n\nThe massive Shadow-Soured squash have begun to grow all over the place. They're stinky and crawling with nasty mites.\n\nMom and Dad brought in some airships to help us yank them out, but it's risky business with all those bugs.\n\nCan you attach ropes to these Shadow-Soured Squash, and the airships can then haul them away without making a mess?", progress = "Have you removed all the Squash?", completion = "You did it! I heard stories of one time the squash was so heavy the airship crashed! Glad that didn't happen.", objectives = "Remove 8 Shadow-Sour Squash and slay 10 Shadow-Sour Mites.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78918] = { id = 78918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brax's Brass Knuckles", description = "I have a proposition for you.\n\nWe get some rowdy patrons here from time to time. Nothing sinister, but our folk work hard and things can get out of hand faster than a dropped hammer. \n\nUsually I'd give 'em a considerate knock upside the head to remind them what's what, but I lost my brass knuckles while helping Watcher Toki clear monsters on the town's skirts.\n\nMind fetching my knuckles and administering some love taps?", progress = "Now which beasts did I punch with those knuckles last...", completion = "That's the genius of the knuckles. They keep your hands intact!", objectives = "Kill creatures around Gundargaz to find Brax's Brass Knuckles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78929] = { id = 78929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tricks of the Dark", description = "Kobyss lurk in the shallows of murky water and snatch any who come near, faster than a viper!\n\nAnd that's just when they hunt alone. In numbers, they are a swarm to be reckoned with. They've been a plague on our outskirt villages since the day we arrived. \n\nThey eat victims alive, given the chance. We must rescue the villagers that have already been dragged to the water!", completion = "Thank you, {name}. These people are badly hurt, but I think they will make it. Some seem to have some skill in healing of their own.", objectives = "Rescue 5 Arathi captives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78931] = { id = 78931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technoscrying: The Mysteries of Dragonskull Island" }
quests[78932] = { id = 78932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fickle Fiendish Fish", description = "Judging by the glint in your eye, you wish to join Faerin in this madness?\n\nTo push into the kobyss waters? In the darkness?\n\nYou are a fool with a death wish. \n\nTake as many of those damnable fish out as you can, before they drag you into the depths for their dinner.", progress = "We can't abandon the villagers here!", completion = "These foes are relentless.", objectives = "Kill 13 kobyss invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78933] = { id = 78933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sweet Eclipse", description = "I've set out to create a dessert that transcends the ordinary, one that even the most devout followers of the light would savor!\n\nTo balance the flavors of the desert, between light and shadow, I require ingredients from several areas within the darkness.\n\nPlease assist me in harvesting the following ingredients: Frog-Kissed Caviar, Darkroot Persimmon and Ethereal Sugar.", progress = "Have you found all of the ingredients?", completion = "Now the magic happens. Please sample this creation for yourself.", objectives = "Collect 8 Darkroot Persimmon, 30 Frog-Kissed Caviar, and 1 Ethereal Sugar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78934] = { id = 78934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blades of the Arathi", description = "I trust in your strength. I must ask you to go ahead to reinforce Sina's Yearning. Anduin and I can see my people to safety in Lorel's Crossing.\n\nWith the darkness and the kobyss, the hearts of my people in Sina's Yearning will be faltering to fear. We can't let them wallow.\n\nLight a torch with the Sacred Flame in the center of town and use it to inspire my people's valor. Remind them of their strength.\n\nWe will catch up with you. May the Flame guide you, my friend.", completion = "The Arathi are strong. Proud. The kobyss may be vile but they will not win this day.", objectives = "Light a torch with the Sacred Flame, then rally 6 groups of Arathi in Sina's Yearning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78936] = { id = 78936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something's Fishy", description = "So you outsiders and Faerin managed to both survive and save the villagers at the beach? \n\n<Steelstrike breathes a quick prayer in relief.> \n\nWe're in trouble, here. The kobyss brought some of their strongest forces to the doorsteps of villagers. \n\nWe have our hands full just holding the line. If you can take out those monsters, we might be able to turn the tide.", progress = "When we first encountered the kobyss, there were those among us who tried to establish peace with them. But it quickly became apparent that they only see us as food.", completion = "Every Arathi has killed more kobyss than I care to count. We've also lost more Arathi to kobyss than I want to count. \n\nI don't know what underwater cavern they hail from... but I shudder to think of it.", objectives = "Slay Deepsludger, The Abominable Wavecrasher, and Tidelord Teethwretch in Sina's Yearning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78937] = { id = 78937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow upon Shadow", description = "<Faerin's wide eyes dart around in surprise.>\n\nWhat just happened? Did you see that shadow? And the oil well... it's gone dark? \n\nI've never seen anything like this before. \n\nCould it be the nearby dawntower? Hurry!", completion = "The fear and shame of these people lingers in the air like a fog.", objectives = "Investigate the nearby dawntower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78938] = { id = 78938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion of the Waterlords", description = "I regret to inform you that a horrific threat awaits your kind within this mortal realm. An Elemental Lord of Fire, Ragnaros, bides his time waiting to strike and burn your Azeroth to its core. We, the elements of water, have waged war eternal with those beings of the lesser elementals. Trust that our warning is no small thing.\n\nProve your conviction! Slay Ragnaros, once and for all!", progress = "Ragnaros yet remains, mortal. His foul heat emanates from nearby.", completion = "You have done what most of your kind would think impossible. You have faced Ragnaros and triumphed!\n\nFor so small a creature, you have displayed great resource.\n\nSome day, perhaps we might strike a true allegiance between your kind and the Waterlords.", objectives = "Defeat Remembered Ragnaros during a Radiant Echoes event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78939] = { id = 78939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkened Flame", description = "This... Order of Night, as they call themselves, did some foul ritual to turn the tower's flame to darkness. I know not what.\n\nWe should investigate.", progress = "My own people... how could they? \n\n<Faerin shakes her head in disbelief.>", completion = "So, they killed Kelther, too? \n\n<Faerin squeezes her eyes shut and mouths a prayer and a curse at the same time.>\n\nWe'll make sure he gets a proper funeral. The Order of Night will pay for this.\n\nWe sealed off Gloomcrag, the nearby cave, years ago. They must have dug their way in so they could target this dawntower. \n\nHow long have they been planning this? How long has the Order of Night been among our ranks?", objectives = "Investigate the darkened dawntower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78940] = { id = 78940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest 00", description = "Placeholder for RP/Pacing as needed." }
quests[78941] = { id = 78941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tide Needing Turned", description = "Xal'atath's army has been capable of striking at us for a while now. So what caused her to choose this moment?\n\nSomething is wrong here. She waited for us to build an army in response, and then attacks openly. We're playing into her hands.\n\nReport to the Arathi general. I'll head to the battlefield directly.", completion = "Good, you're here. I'll keep it brief.", objectives = "Meet with General Steelstrike in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78942] = { id = 78942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of Khaz Algar", description = "The Harbinger thinks she can catch us off guard, but she's a fool if she expects to win this fight.\n\nThe Algari Offensive stands at your back, {name}. Spare no enemy.", completion = "Your Horde and Alliance make a formidable army. I don't think there's much we could have done without them.", objectives = "Fight back against the nerubians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78943] = { id = 78943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steel and Flames", description = "Our forces may be able to hold their own, but seeing you in the fray may help their spirits. \n\nTake this warhorn. Let it ring out and fill our foes with terror. Once you're done rallying our troops, make your way to your commanders.", completion = "You've arrived just in time.", objectives = "Rally 20 Algari Offensive troops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78948] = { id = 78948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in the Dark", description = "Something is very wrong. As the battle continues, each side has become more aggressive.\n\nAlleria seems to know something - she ran off at one point during the battle. We've been giving chase, but I cannot leave these soldiers to die. She's just ahead, we can reconvene with her together.", completion = "Khadgar will need immediate help. We will have time for celebrations later.", objectives = "Speak with Anduin and chase down Xal'atath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78950] = { id = 78950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Off the Legs", description = "While we've yet to locate Xal'atath, we've received reports from deeper in the field of certain nerubians giving orders. It won't buy us too much but every action is critical.\n\nTake them out. Hopefully that will allow us some breathing room. \n\nSpeak with Anduin after you are done. He and the Arathi girl went after Alleria.", progress = "Speak with Anduin within the Sanguine Grasps.", completion = "Oh, good, you made it.", objectives = "Slay the nerubian lieutenants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78951] = { id = 78951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ever Deeper Shadow", description = "When I reached for the Flame, I felt the overwhelming hopelessness and despair that had been poured into it. \n\nIt pains me, but... my light alone is not enough to banish these shadows. \n\nAnd so, we take a more direct path. If the remaining cultists have withdrawn to Gloomcrag Bower, their combined power must be what's keeping the Flame dark. \n\nWe must stop them before this darkness spreads.", progress = "These were once my people. My allies. My mentors. \n\nI once tried to reason with them. Tried to make them see the Light... see that the Light is still within us all.\n\n<Faerin's face flickers between sadness and anger.>\n\nThey wouldn't listen. And they're killing innocents. \n\nI can't hesitate. Not anymore.", completion = "<Faerin's jaw is firm.> \n\nThey made their choice.", objectives = "Slay 10 Order of Night cultists in the cave beneath the Cliffside Beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
